// Group papers by (topic, year) and compute weighted stance percentages
// using methodology_score as the weight.

const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && Object.keys(r).length > 0);

const STANCES = ['supports', 'contradicts', 'neutral', 'mixed'];

const groups = {};
const topicSet = new Set();
const yearSet = new Set();

for (const r of rows) {
  const topic = r.topic != null ? String(r.topic) : '';
  const year = (typeof r.year === 'number') ? r.year : (r.year != null ? Number(r.year) : null);
  if (year === null || Number.isNaN(year)) continue;

  const stance = r.stance != null ? String(r.stance) : '';
  let weight = (typeof r.methodology_score === 'number')
    ? r.methodology_score
    : (r.methodology_score != null ? Number(r.methodology_score) : 0);
  if (!Number.isFinite(weight)) weight = 0;

  topicSet.add(topic);
  yearSet.add(year);

  const key = topic + '||' + year;
  if (!groups[key]) {
    groups[key] = {
      topic,
      year,
      weightByStance: { supports: 0, contradicts: 0, neutral: 0, mixed: 0 },
      totalWeight: 0,
      papers_count: 0,
    };
  }
  const g = groups[key];
  g.papers_count += 1;
  g.totalWeight += weight;
  if (STANCES.includes(stance)) {
    g.weightByStance[stance] += weight;
  }
}

function pct(part, total) {
  if (!total || total === 0) return 0;
  return Math.round((part / total) * 10000) / 100; // percentage, 2 decimals
}

const out = [];
for (const key of Object.keys(groups)) {
  const g = groups[key];
  const avg = g.papers_count > 0
    ? Math.round((g.totalWeight / g.papers_count) * 100) / 100
    : 0;

  out.push({
    json: {
      topic: g.topic,
      year: g.year,
      weighted_support: pct(g.weightByStance.supports, g.totalWeight),
      weighted_contradiction: pct(g.weightByStance.contradicts, g.totalWeight),
      weighted_neutral: pct(g.weightByStance.neutral, g.totalWeight),
      weighted_mixed: pct(g.weightByStance.mixed, g.totalWeight),
      papers_count: g.papers_count,
      average_methodology_score: avg,
      __topics_processed: topicSet.size,
      __years_processed: yearSet.size,
    },
  });
}

if (out.length === 0) {
  return [{ json: { __empty: true, __topics_processed: 0, __years_processed: 0 } }];
}

return out;

// Rows actually written = rows returned by the upsert query.
const written = $input.all().filter((i) => i.json && Object.keys(i.json).length > 0);
const rows_written = written.length;

const computed = $('Compute Consensus').all().map((i) => i.json);
const first = computed[0] || {};
const topics_processed = first.__topics_processed || 0;
const years_processed = first.__years_processed || 0;

return [{ json: { topics_processed, years_processed, rows_written } }];
